import sympy
from sympy import *

def pre_condition_0(y:sympy.Rational):
	#Eq(y, 0)

	pre_cond = Equality(Symbol('y'), Integer(0))

	eval = pre_cond.subs( { 'y':y })

	if eval==True:
		assert eval!=False
		return True
	return False


